  "adminPricing.priceBooks.review.policyBasis": {
    en: "Commercial policy CP-2 requires versioned rate cards, explicit routes, regional floors and two finance approvers.",
    es: "La política comercial CP-2 exige tarifas versionadas, modalidades de venta explícitas, precios mínimos por región y dos aprobadores financieros.",
    fr: "La politique commerciale CP-2 exige des barèmes tarifaires versionnés, des modes de vente explicites, des prix plancher régionaux et deux approbateurs financiers.",
    de: "Die kaufmännische Richtlinie CP-2 verlangt versionierte Preisblätter, ausdrücklich festgelegte Vertriebswege, regionale Preisuntergrenzen und zwei genehmigende Personen aus dem Finanzbereich.",
    ja: "商取引ポリシー CP-2 では、バージョン管理された料金表、明示された販売形態、リージョン別の下限価格、2名の財務承認者が必要です。",
    pt: "A política comercial CP-2 exige tabelas de tarifas versionadas, modalidades de venda explícitas, preços mínimos regionais e dois aprovadores financeiros.",
    zh: "商务政策 CP-2 要求费率表有版本管理、销售模式明确、按区域设置底价，并由两名财务审批人审批。",
    ar: "تشترط السياسة التجارية CP-2 جداول أسعار ذات إصدارات، ومسارات بيع محددة صراحةً، وحدودًا دنيا للأسعار حسب المنطقة، وموافِقَين ماليين اثنين.",
  },
  "adminPricing.priceBooks.review.downstream.cancel": {
    en: "No price book is activated or retired. The cancellation and the earlier approval stay in the history; this draft needs a new proposal and approval by a different finance approver before any later activation.",
    es: "No se activa ni se retira ninguna lista de precios. La cancelación y la aprobación anterior quedan en el historial; este borrador necesita una nueva propuesta y la aprobación de otro aprobador financiero antes de cualquier activación posterior.",
    fr: "Aucune grille tarifaire n’est activée ni retirée. L’annulation et l’approbation antérieure restent dans l’historique\u202f; ce brouillon nécessite une nouvelle proposition et l’approbation d’un autre approbateur financier avant toute activation ultérieure.",
    de: "Es wird keine Preisliste aktiviert oder außer Kraft gesetzt. Die Aufhebung und die frühere Genehmigung bleiben im Verlauf erhalten; dieser Entwurf braucht vor jeder späteren Aktivierung einen neuen Antrag und die Genehmigung durch eine andere Person aus dem Finanzbereich.",
    ja: "価格表の有効化や廃止は行われません。取り消しと以前の承認は履歴に残ります。今後有効化するには、この下書きを再申請し、別の財務承認者の承認を得る必要があります。",
    pt: "Nenhuma tabela de preços é ativada ou descontinuada. O cancelamento e a aprovação anterior permanecem no histórico; este rascunho precisa de uma nova proposta e da aprovação de outro aprovador financeiro antes de qualquer ativação posterior.",
    zh: "不会启用或停用任何价目表。取消操作和此前的批准会保留在历史记录中；此草稿在今后启用前需要重新申请，并由另一名财务审批人批准。",
    ar: "لا تُفعَّل أي قائمة أسعار ولا تُوقف. يبقى الإلغاء والموافقة السابقة في السجل، وتحتاج هذه المسودة إلى اقتراح جديد وموافقة موافِق مالي مختلف قبل أي تفعيل لاحق.",
  },
  "adminPricing.priceBooks.review.downstream.approve": {
    en: "Activation makes this version eligible for new pricing. Retained quote, order, invoice and collection economics stay unchanged; retiring the current book stops draft issuance and revisions on it.",
    es: "La activación hace que esta versión pueda usarse para calcular nuevos precios. Las condiciones económicas de los presupuestos, pedidos, facturas y cobros ya registrados no cambian; al retirar la lista vigente, dejan de emitirse borradores y revisiones con ella.",
    fr: "L’activation rend cette version utilisable pour les nouveaux calculs de prix. Les données économiques des devis, commandes, factures et encaissements existants restent inchangées\u202f; le retrait de la grille en vigueur met fin à l’émission de brouillons et de révisions à partir de celle-ci.",
    de: "Durch die Aktivierung kann diese Version für neue Preisermittlungen verwendet werden. Die Konditionen bestehender Angebote, Aufträge, Rechnungen und Zahlungseingänge bleiben unverändert; wird die aktuelle Preisliste außer Kraft gesetzt, werden daraus keine Entwürfe und Überarbeitungen mehr ausgestellt.",
    ja: "有効化すると、このバージョンが新たな価格計算に使用できるようになります。既存の見積もり、注文、請求書、回収の経済条件は変わりません。現行の価格表を廃止すると、その価格表からの下書き発行と改訂は停止します。",
    pt: "A ativação torna esta versão elegível para novos cálculos de preço. As condições econômicas de cotações, pedidos, faturas e recebimentos já registrados não mudam; descontinuar a tabela vigente encerra a emissão de rascunhos e revisões a partir dela.",
    zh: "启用后，此版本可用于新的定价计算。已保留的报价、订单、发票和收款的经济条款保持不变；停用当前价目表后，将不再基于它出具草稿和修订版。",
    ar: "يجعل التفعيل هذا الإصدار مؤهلًا لعمليات التسعير الجديدة. تبقى الشروط الاقتصادية لعروض الأسعار والطلبات والفواتير والتحصيلات القائمة دون تغيير، ويؤدي إيقاف القائمة الحالية إلى وقف إصدار المسودات والنسخ المعدّلة منها.",
  },
