  "adminPricing.discounts.intro": {
    en: "Ceilings are in basis points: 100 = 1%. A matching rule can raise the default ceiling; the highest matching ceiling applies. Regional floor prices still apply. Changes require a new two-person activation.",
    es: "Los límites se expresan en puntos básicos: 100 = 1 %. Una regla aplicable puede elevar el límite predeterminado; se aplica el límite más alto entre las reglas aplicables. Los precios mínimos regionales se siguen aplicando. Cualquier cambio requiere una nueva activación aprobada por dos personas.",
    fr: "Les plafonds sont exprimés en points de base\u00a0: 100 = 1\u202f%. Une règle applicable peut relever le plafond par défaut\u202f; le plus élevé des plafonds applicables l’emporte. Les prix planchers régionaux continuent de s’appliquer. Toute modification exige une nouvelle activation approuvée par deux personnes.",
    de: "Obergrenzen werden in Basispunkten angegeben: 100 = 1 %. Eine zutreffende Regel kann die Standardobergrenze anheben; es gilt die höchste zutreffende Obergrenze. Regionale Preisuntergrenzen gelten weiterhin. Jede Änderung erfordert eine neue Aktivierung durch zwei Personen.",
    ja: "上限はベーシスポイントで指定します（100 = 1%）。条件に一致するルールは既定の上限を引き上げることができ、一致したルールのうち最も高い上限が適用されます。リージョンごとの下限価格は引き続き適用されます。変更には、2名による新たな有効化の承認が必要です。",
    pt: "Os tetos são expressos em pontos-base: 100 = 1%. Uma regra aplicável pode elevar o teto padrão; vale o maior teto entre as regras aplicáveis. Os preços mínimos regionais continuam valendo. Qualquer alteração exige uma nova ativação aprovada por duas pessoas.",
    zh: "上限以基点表示：100 = 1%。匹配的规则可以提高默认上限，以匹配规则中最高的上限为准。各区域底价仍然适用。任何更改都需要重新经过双人审批启用。",
    ar: "تُحدَّد الحدود القصوى بنقاط الأساس: 100 = 1%. يمكن لقاعدة مطابقة أن ترفع الحد الأقصى الافتراضي، ويُطبَّق أعلى حد أقصى بين القواعد المطابقة. تظل الحدود الدنيا الإقليمية للأسعار سارية. يتطلب أي تغيير تفعيلًا جديدًا يوافق عليه شخصان.",
  },
