    pt: "Visualize as tarifas salvas e a alçada de desconto na data de vigência. Isso não ativa nenhuma tabela de preços nem cria uma cotação. A tarifação do uso no pagamento conforme o uso e os mínimos mensais seguem uma política de faturamento separada.",
    zh: "按生效日期预览已保存的费率和折扣权限。此操作不会启用价目表，也不会创建报价。按量付费的用量计费和每月最低消费由单独的计费策略管理。",
