  "adminPricing.impact.footnote": {
    en: "Revisions and orders are separate counts and must not be added together. Agreements count distinct governing records, not new contracts created by activation. Entitlements describe retained state, not a live provider check. Revenue, margin and renewal forecasts require additional approved inputs.",
    es: "Las revisiones y los pedidos son recuentos independientes y no deben sumarse. Los acuerdos cuentan registros rectores distintos, no contratos nuevos creados por la activación. Los derechos de uso describen el estado conservado, no una comprobación en tiempo real con el proveedor. Las previsiones de ingresos, margen y renovaciones requieren datos adicionales aprobados.",
    fr: "Les révisions et les commandes sont des décomptes distincts qui ne doivent pas être additionnés. Les accords comptent des enregistrements de référence distincts, et non de nouveaux contrats créés par l’activation. Les droits d’utilisation décrivent l’état conservé, pas une vérification en direct auprès du prestataire. Les prévisions de chiffre d’affaires, de marge et de renouvellement nécessitent des données supplémentaires approuvées.",
    de: "Überarbeitungen und Aufträge werden getrennt gezählt und dürfen nicht addiert werden. Bei Vereinbarungen werden unterschiedliche maßgebliche Datensätze gezählt, keine durch die Aktivierung neu entstandenen Verträge. Nutzungsrechte beschreiben den gespeicherten Stand, keine Live-Prüfung beim Anbieter. Umsatz-, Margen- und Verlängerungsprognosen erfordern zusätzliche genehmigte Eingaben.",
    ja: "改訂版と注文は別々の件数であり、合算しないでください。契約は、有効化によって新たに作成された契約ではなく、個別の準拠契約記録を数えています。利用権は保存済みの状態を示すもので、プロバイダーへのリアルタイム確認ではありません。売上、利益率、契約更新の予測には、承認済みの追加データが必要です。",
    pt: "Revisões e pedidos são contagens separadas e não devem ser somados. Os acordos contam registros vigentes distintos, não novos contratos criados pela ativação. Os direitos de uso descrevem o estado retido, não uma verificação em tempo real no provedor. Previsões de receita, margem e renovação exigem dados adicionais aprovados.",
    zh: "修订版和订单分别计数，不得相加。协议统计的是不同的适用协议记录，而不是因启用而新建的合同。权益反映的是已保留的状态，并非对服务商的实时核查。收入、利润率和续约预测需要额外的已批准输入。",
    ar: "النسخ المعدّلة والطلبات أعداد منفصلة ولا يجوز جمعها معًا. تُحصى الاتفاقيات بوصفها سجلات حاكمة مميزة، لا عقودًا جديدة أنشأها التفعيل. تصف الاستحقاقات الحالة المحفوظة، لا تحققًا مباشرًا لدى المزوّد. تتطلب توقعات الإيرادات والهامش والتجديد مدخلات إضافية معتمدة.",
  },
